from pathlib import Path
from html import escape
from datetime import date
import json, os
R=Path(__file__).resolve().parent
SPECIMENS=[{'id':f'tree-{n:02d}','number':n,'title':f'Tree {n:02d}','species':'Acer rubrum','origin':'Seed-grown · 2026','status':'Design study / planned' if n==1 else 'Early cultivation / observation','description':"The owner's first bonsai experiment, with a proposed root-over-rock direction. Stone selection, repotting, and root placement remain future work." if n==1 else 'A separate seed-grown red maple. Its measurements, photographic history, and styling direction have not yet been documented.'} for n in range(1,6)]
NAV=[('collection','Collection'),('chronicle','Chronicle'),('atelier','Atelier'),('journal','Field Journal'),('practice','Practice'),('about','About')]
def link(target,current=''):
    if target=='': tgt='index.html'
    else: tgt=target.strip('/')+'/index.html'
    src=R/current if current else R
    return os.path.relpath(R/tgt,src).replace(os.sep,'/')
def A(label,target,current,cl='editorial-link'):
    return f'<a class="{cl}" href="{link(target,current)}">{label}<span class="arrow" aria-hidden="true">↗</span></a>'
def cpath(current,p):
    return os.path.relpath(R/p,R/current if current else R).replace(os.sep,'/')
def image(file,current,alt='',cl='',loading='lazy'):
    return f'<img class="{cl}" src="{cpath(current,"media/"+file)}" alt="{escape(alt)}" loading="{loading}" decoding="async" width="1536" height="1024">'
def header(current):
    nav=''.join(f'<a href="{link(path,current)}"'+(' aria-current="page"' if (current==path or current.startswith(path+'/')) else '')+f'>{text}</a>' for path,text in NAV)
    return f'<a class="skip" href="#main">Skip to content</a><header class="site-header{" is-inside" if current else ""}"><div class="wrap header-inner"><a class="wordmark" href="{link("",current)}" aria-label="ANEVUM — Home">ANEVUM<small>A LIVING ATLAS</small></a><nav aria-label="Primary" class="desktop-nav">{nav}</nav><div class="header-note">2026 — ∞</div><details class="mobile-nav"><summary aria-label="Open navigation">Menu</summary><nav aria-label="Mobile">{nav}</nav></details></div></header>'
def footer(current):
    nav=''.join(f'<a href="{link(path,current)}">{text}</a>' for path,text in NAV)
    return f'<footer class="footer"><div class="wrap"><div class="footer-grid"><div><div class="footer-mark">ANEVUM</div><p class="text-prose">A living atlas of trees, time, and the art of becoming.</p></div><nav aria-label="Footer">{nav}</nav></div><div class="footer-small"><span>Independent collection and botanical journal · Founded 2026</span><span>Concept scenery is illustrative. Real specimen photography forthcoming.</span></div></div></footer>'
def page(current,title,desc,body):
    css=cpath(current,'assets/site.css');js=cpath(current,'assets/site.js')
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0b1710"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="description" content="{escape(desc)}"><meta property="og:site_name" content="ANEVUM — A Living Atlas"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><title>{escape(title)} — ANEVUM, A Living Atlas</title><link rel="stylesheet" href="{css}"><script type="module" src="{js}" defer></script></head><body>{header(current)}<main id="main" tabindex="-1">{body}</main>{footer(current)}</body></html>'''
    target=R/current/'index.html' if current else R/'index.html'
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(html,encoding='utf-8')

def eyebrow(name,light=True):return f'<div class="section-label{" light" if light else ""}">{name}</div>'
def scene(current,file='hero-desktop.webp',label='Illustrative environment · not a photograph of the collection'):
    return f'<div class="scene-image">{image(file,current,"Illustrative study of a young maple seedling among moss-covered rocks") }<span class="media-label">{label}</span></div>'
def inside(current,eyebrow_text,title,description,count=''):
    return f'<section class="inside-hero"><div class="wrap inside-hero-split"><div>{eyebrow(eyebrow_text)}<h1 class="display">{title}</h1><p class="text-prose">{description}</p></div><div class="callout-count" aria-hidden="true">{count}</div></div></section>'

def homepage():
 current=''
 hero=f'''<section class="scene hero"><picture class="hero-picture"><source media="(max-width:730px)" srcset="{cpath(current,'media/hero-mobile.webp')}">{image('hero-desktop.webp',current,'',loading='eager')}</picture><div class="wrap hero-content"><div class="eyebrow">ANEVUM / A living atlas · est. 2026</div><h1>Time is<br><em>the medium.</em></h1><p class="hero-sub">Five trees raised from seed. A living atlas of time, patience, and the art of becoming.</p><div class="hero-actions">{A('Enter the collection','collection',current,'link-cta')}{A('Explore the Chronicle','chronicle',current,'link-cta outline')}</div></div><div class="wrap hero-bot"><div><div class="topline"></div><div class="micro">Scroll to discover &nbsp; 01 / 05</div></div><span class="disclosure">Cinematic concept · Not actual specimen photography</span></div></section>'''
 intro=f'''<section class="intro"><div class="wrap"><div class="feature-intro"><div>{eyebrow('I / The founding collection',False)}<h2 class="display">Worlds<br><em>grown</em> slowly.</h2></div><p class="text-prose">Five surviving <em>Acer rubrum</em> seedlings, grown from seed in 2026. Small enough to hold in your hands, young enough that almost their entire story can still be documented.</p></div><div class="collection-stage">{scene(current)}<div class="side-feature"><div class="big-id">01</div><div>{eyebrow('Specimen 01 · First experiment')}<h3>The earliest<br>chapter.</h3><p>One tiny red maple. An imagined root-over-rock composition. The actual tree has not yet been worked or mounted to stone.</p>{A('Enter Specimen 01','collection/tree-01',current)}</div></div></div><div class="collection-index">{''.join(specimen_tile(s,current) for s in SPECIMENS[1:])}</div></div></section>'''
 narrative=f'''<section class="narrative"><div class="wrap"><div class="narrative-grid"><div>{eyebrow('II / The philosophy')}<h2 class="display">Not a finished<br>thing.<br><em>A becoming.</em></h2><p class="text-prose">We are not collecting impressive endings. We are building the record of how living forms arise, change, and respond to deliberate care. The questions matter as much as the answers.</p>{A('Our Practice','practice',current)}</div><div class="ring-engraving" aria-hidden="true"><span>∞</span></div></div><div class="facts-line"><div><strong>05</strong><span>Seed-grown red maples</span></div><div><strong>2026</strong><span>Founding year</span></div><div><strong>∞</strong><span>Years of observation ahead</span></div></div></div></section>'''
 chronicle=f'''<section class="chapter on-paper"><div class="wrap"><div class="chronicle-preview"><div>{eyebrow('III / The Chronicle',False)}<h2 class="display sm">A different<br>kind of clock.</h2><p class="text-prose">A timeline composed of real moments. Observed growth. Planned interventions. Completed work. These are never interchangeable.</p>{A('Follow the first records','chronicle',current)}</div><div><div class="date-engraving" aria-hidden="true">2026</div><div class="timeline-line"><span>SEED</span><i></i><span>YEARS</span><i></i><span>TIME</span></div><p class="note-line">15 November 2026 / First design direction</p></div></div></div></section>'''
 atelier=f'''<section class="chapter dark"><div class="wrap"><div class="chapter-header"><div>{eyebrow('IV / The Living Atelier')}<h2 class="display sm">Design begins<br>with <em>seeing.</em></h2></div><p class="text-prose">The first investigation: finding a stone and an eventual root-over-rock language for Tree 01. A design studio for proposed futures, clearly separate from what has happened.</p></div><div class="two-column"><div class="graphic-panel vignette">{image('stone-study.webp',current,'Illustrative close-up of a mossy rock surface, not a rock selected for the collection')}<div class="panel-folio"><strong>Form before<br>intervention.</strong><span>Study material / illustrative</span></div></div><div><p class="eyebrow">Tree 01 / Study 001</p><h3 class="paper-quote">A stone is not simply an object. It becomes the landscape against which a tree can grow.</h3><p class="text-prose">Three compositional possibilities. No stone selected. No roots manipulated. All options remain experimental.</p><br>{A('Enter the Atelier','atelier',current)}</div></div></div></section>'''
 journal=f'''<section class="chapter on-paper"><div class="wrap"><div class="chapter-header"><div>{eyebrow('V / Field Notes',False)}<h2 class="display sm">An archive<br>in the making.</h2></div><p class="text-prose">Photographic records will gradually replace illustrative scenes. An honest journal begins before its first spectacular photograph.</p></div><a class="journal-row" href="{link('journal/time-is-the-medium',current)}"><span class="date">15 NOV 2026</span><div><h2>Time is the medium</h2><p>The inaugural editorial record of five seed-grown trees and their future.</p></div><span class="arrow" aria-hidden="true">↗</span></a></div></section>'''
 page(current,'Home','A living atlas of five seed-grown red maples and the art of becoming.',hero+intro+narrative+chronicle+atelier+journal)

def specimen_tile(s,current):
 return f'''<a class="specimen-tile" href="{link('collection/'+s['id'],current)}"><span class="section-label">ACER RUBRUM / {s['number']:02d}</span><span class="tile-num">{s['number']:02d}</span><div class="tile-bottom"><div><h3>{s['title']}</h3><p>Seed-grown · 2026</p></div><span class="arrow" aria-hidden="true">↗</span></div></a>'''

def collection():
 current='collection'
 h=inside(current,'The Collection / 2026','Five lives.<br><em>One beginning.</em>','Five separate red maples. One origin year. Individual identities and histories emerge as observations and original photographs are recorded.','05')
 rows=''
 for s in SPECIMENS:
  num=s['number']; art=scene(current,'light-study.webp','Illustrative botanical scene · not Tree 01') if num==1 else f'<div class="collection-art"><span class="number-ghost" aria-hidden="true">{num:02d}</span><span class="art-label">Documentary photograph pending / Tree {num:02d}</span></div>'
  if num==1: art=f'<div class="collection-art">{image("light-study.webp",current,"Illustrative plant study, not the real specimen")}<span class="art-label">Illustrative botanical study · not Tree 01</span></div>'
  rows+=f'''<article class="collection-row"><div>{art}</div><div class="record-detail"><span class="section-label light">SPECIMEN {num:02d} / 05</span><h2 class="display">{s['title']}</h2><p class="text-prose"><em>Acer rubrum</em> · Red maple · {s['origin']}</p><p class="text-prose">{s['description']}</p><div style="margin-top:1.6rem">{A('Open living record','collection/'+s['id'],current)}</div></div></article>'''
 provision=f'''<aside class="provisional"><div>{eyebrow('Separate field experiment',False)}<h3>The Acorn Experiment</h3><p>An acorn transplanted after signs of possible germination. Its botanical identification and survival remain unverified.</p></div><div><p>Not included among the five Acer rubrum records. A small experiment with a story of its own.</p>{A('Read provisional field note','field-notes/acorn-01',current)}</div></aside>'''
 page(current,'Collection','Five seed-grown red maple records with honest media provenance.',h+f'<section class="dark"><div class="wrap">{rows}</div></section><section class="on-paper chapter"><div class="wrap">{provision}</div></section>')

def specimen_page(s):
 current='collection/'+s['id'];n=s['number']
 h=inside(current,f'Specimen {n:02d} / Acer rubrum',s['title'],f'Born of seed in 2026. A living record of {"the first proposed root-over-rock design" if n==1 else "a young red maple whose individual history is still being documented"}.',f'{n:02d}')
 pic=f'<div class="visual">{image("hero-desktop.webp",current,"Illustrative young sapling scene, not a photograph of Tree 01")}<span class="media-label">Illustrative composition · Real Tree 01 photography pending</span></div>' if n==1 else f'<div class="visual" style="background:radial-gradient(ellipse at 60% 40%,#3f5038,#142619 57%,#07150e)"><div class="callout-count" style="padding:3rem;text-align:center;font-size:12rem">{n:02d}</div><span class="media-label">Actual specimen photography pending</span></div>'
 meta=[('Species','Acer rubrum · Red maple'),('Origin','Seed-grown in 2026'),('Germination date','Not recorded'),('Current measurements','Not recorded'),('Current health status','Not evaluated'),('Design direction','Root-over-rock · proposed only' if n==1 else 'Not established'),('Completed interventions','None documented')]
 metas='<dl class="metadata">'+''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in meta)+'</dl>'
 stage=f'<section class="wrap chapter" style="padding-top:0"><div class="record-stage">{pic}<div class="description">{eyebrow("Record / 2026")}<div><h2>Becoming,<br><em>slowly.</em></h2><p class="text-prose">{s["description"]}</p><span class="status">DOCUMENTATION IN PROGRESS</span></div>{A("View the Chronicle","chronicle",current)}</div></div><div class="stat-grid"><div><b>2026</b><span>Recorded origin year</span></div><div><b>{n:02d}/05</b><span>Collection sequence</span></div><div><b>—</b><span>Measurements not yet recorded</span></div></div><div class="two-column" style="align-items:start"><div>{eyebrow("The current record")}<h2 class="display sm">What we<br><em>know.</em></h2><p class="text-prose">{s["description"]}</p>{A('Open design study','atelier',current) if n==1 else ''}</div><div>{eyebrow('Metadata & provenance')}{metas}</div></div><nav aria-label="Browse specimen records" class="record-navigation">'+''.join(f'<a href="{link("collection/"+p["id"],current)}"'+(' aria-current="page"' if p['id']==s['id'] else '')+f'><span class="num">{p["number"]:02d}</span><span class="label">Tree {p["number"]:02d}</span></a>' for p in SPECIMENS)+'</nav></section>'
 page(current,s['title'],f'Living record for {s["title"]} — seed-grown red maple, 2026.',h+stage)

def chronicle():
 current='chronicle';h=inside(current,'The Chronicle / Actual time','Time without<br><em>invention.</em>','Every record knows what happened, what is only being considered, and what is still unknown. No manufactured before-and-after evidence.','2026')
 entries=[('2026','OBSERVED','observed','The founding collection','Five seed-grown Acer rubrum survive in the founding collection. Their precise germination dates are not documented.'),('15 Nov 2026','PLANNED','planned','A root-over-rock direction','Tree 01 is selected as the first root-over-rock design study. The rock is not installed, and root placement has not occurred.')]
 timeline='<ol class="timeline" data-timeline>'+''.join(f'<li data-state="{state}"><time>{date}</time><div><h3>{title}</h3><p>{desc}</p></div><span class="status {state}">{label}</span></li>' for date,label,state,title,desc in entries)+'</ol>'
 filters='<div class="timeline-filters" role="group" aria-label="Filter history"><button type="button" data-filter="all" aria-pressed="true">All records</button><button type="button" data-filter="observed" aria-pressed="false">Observed</button><button type="button" data-filter="planned" aria-pressed="false">Planned</button><button type="button" data-filter="completed" aria-pressed="false">Completed</button></div>'
 body=h+f'<section class="chapter dark"><div class="wrap">{eyebrow("Recorded / 2026 onward")}{filters}{timeline}</div></section><section class="chapter on-paper"><div class="wrap two-column"><div>{eyebrow("Photographic continuity",False)}<h2 class="display sm">A comparison<br>must be <em>real.</em></h2><p class="text-prose">When two genuine dated photographs exist for the same specimen, an interactive comparison will become available. Nothing is simulated while the originals are pending.</p>{A("View the collection","collection",current)}</div><div class="graphic-panel vignette">{image("leaf-study.webp",current,"Illustrative close view of young leaves, not real growth evidence")}<div class="panel-folio"><strong>2026 — ∞</strong><span>Illustrative visual study / not a historical photo</span></div></div></div></section>'
 page(current,'Chronicle','An honest, dated timeline of the five red maples and their experiments.',body)

def atelier():
 current='atelier';h=inside(current,'The Living Atelier / 001','Form, before<br><em>the first cut.</em>','A design laboratory for Tree 01. Explore possible stone silhouettes and root trajectories. All geometry is illustrative; none represents work already performed.','001')
 svg='''<svg class="study-visual" viewBox="0 0 600 320" role="img" aria-label="Illustrative contour drawing of a proposed rock and root-over-rock trajectory"><path class="water" d="M20 284Q180 244 310 282T580 275 M20 299Q170 269 310 297T580 298"/><path class="base" d="M65 277L528 277 509 296H86Z"/><path id="stone-path" class="stone" d="M165 267Q190 192 224 160L249 94 293 140 320 70 372 150 395 224 432 268Z"/><path id="root-path" class="root" d="M290 147Q265 186 255 207T212 267 M292 144Q307 187 351 219T400 268"/><path class="branch" fill="none" d="M291 146V75 M291 95L264 61 M291 102L320 65"/><ellipse class="leaf" cx="260" cy="56" rx="23" ry="12" transform="rotate(20 260 56)"/><ellipse class="leaf" cx="323" cy="60" rx="22" ry="12" transform="rotate(-20 323 60)"/><ellipse class="leaf" cx="289" cy="72" rx="22" ry="13"/></svg>'''
 stage=f'<div class="atelier-stage"><div class="atelier-art">{image("stone-study.webp",current,"Illustrative mossy rock texture, not a selected stone")}<span class="media-label">Conceptual stone study · Candidate rock not selected</span></div><div class="atelier-notes">{eyebrow("Tree 01 / Root-over-rock") }<h2 class="display sm">The stone<br><em>comes first.</em></h2><div class="status">Proposed / Not installed</div>{svg}<div class="study-selector" role="group" aria-label="Stone studies"><button type="button" data-study="vertical" aria-pressed="true">I · Vertical</button><button type="button" data-study="shelter" aria-pressed="false">II · Shelter</button><button type="button" data-study="offset" aria-pressed="false">III · Offset</button></div><p id="study-note" aria-live="polite" class="study-note">Vertical emphasis: investigate a narrow stone with an ascending outline. Root position and rock dimensions are unknown.</p></div></div>'
 body=h+f'<section class="chapter dark"><div class="wrap">{stage}<p class="media-label" style="padding-top:1.5rem">The three line drawings are compositional proposals, not scans of any real tree or stone.</p></div></section><section class="chapter on-paper"><div class="wrap two-column"><div>{eyebrow("Method / Observe first",False)}<h2 class="display sm">An experiment<br><em>not yet begun.</em></h2></div><div><p class="text-prose">Root-over-rock design is a multi-year horticultural decision, not a filter applied to a photograph. Before working with the roots, the tree, season, stone, and root structure must be assessed.</p>{A("Return to Tree 01","collection/tree-01",current)}</div></div></section>'
 page(current,'Living Atelier','Illustrative root-over-rock design studies for Tree 01, with interventions clearly marked planned.',body)

def journal():
 current='journal';h=inside(current,'Field Journal / Editorial archive','Notes from<br><em>the beginning.</em>','Original observations and reflections, archived as the story develops. Planned content is never passed off as field evidence.','01')
 row=f'<a class="journal-row" href="{link("journal/time-is-the-medium",current)}"><time class="date" datetime="2026-11-15">15 NOV 2026</time><div><h2>Time is the medium</h2><p>The inaugural editorial statement: documenting a living collection from its earliest years.</p></div><span class="arrow" aria-hidden="true">↗</span></a>'
 page(current,'Field Journal','Editorial field journal of ANEVUM, begun in 2026.',h+f'<section class="chapter on-paper"><div class="wrap">{eyebrow("Entry 001",False)}{row}<p style="font:.82rem var(--sans);color:#697363">Additional entries will be published as observations and owner-approved photographs are available.</p></div></section>')

def journal_entry():
 current='journal/time-is-the-medium';h=inside(current,'Field Journal / 15 November 2026','Time is<br><em>the medium.</em>','An inaugural editorial statement about a new collection, not a fabricated horticultural field report.','001')
 paragraphs=["ANEVUM begins with five living red maples, grown from seed in 2026. They do not look like the finished bonsai commonly displayed in exhibitions. Their unfinished nature is exactly why they belong in this collection.","The first tree carries a future possibility: a root-over-rock composition. That possibility is still a study. No stone has been selected or installed. The living tree will eventually determine what is practical.","This archive will record what happens, not just what looks impressive: dates, mistakes, photographs, seasons, questions, interventions, and the long spans between visible change.","The photographs are coming. Until then, illustrative botanical imagery serves only as creative atmosphere. It will never be confused with a historical record of these trees."]
 text=''.join(f'<p>{escape(p)}</p>' for p in paragraphs)
 page(current,'Time is the medium','Inaugural ANEVUM editorial statement dated 2026-11-15.',h+f'<section class="chapter on-paper"><div class="wrap"><div class="journal-entry">{eyebrow("Editorial draft / 2026",False)}{text}<p style="font-style:italic">The work of becoming does not require an audience. It requires time.</p></div><div style="display:flex;justify-content:center;margin-top:3rem">{A("Return to Journal","journal",current)}</div></div></section>')

def practice():
 current='practice';h=inside(current,'The practice / Observation','Care as<br><em>an art of time.</em>','Bonsai and penjing begin with living material, careful attention, and respect for change. The design is an intention, not an entitlement.','∞')
 body=h+f'<section class="chapter on-paper"><div class="wrap two-column"><div>{eyebrow("01 / Cultivation",False)}<h2 class="display sm">Begin with<br><em>what is real.</em></h2><p class="text-prose">A specimen portrait should show the actual tree, soil, and container as they are. Records distinguish observation from hypothesis and interventions from plans.</p></div><div class="graphic-panel vignette">{image("leaf-study.webp",current,"Illustrative close view of maple leaves")}<div class="panel-folio"><strong>Look longer.</strong><span>Illustrative botanical study</span></div></div></div></section><section class="chapter dark"><div class="wrap two-column"><div class="graphic-panel vignette">{image("stone-study.webp",current,"Illustrative stone surface lit in woodland light")}<div class="panel-folio"><strong>Imagine later.</strong><span>Stone selection · future study</span></div></div><div>{eyebrow("02 / The art of arrangement")}<h2 class="display sm">Landscapes<br><em>in miniature.</em></h2><p class="text-prose">Penjing composition, bonsai form, rock, negative space, and proportion offer artistic directions. They remain suggestions until they can be reconciled with the biology of each living tree.</p>{A("View the Atelier","atelier",current)}</div></div></section>'
 page(current,'Practice','The cultivation philosophy behind ANEVUM and its bonsai/penjing experiments.',body)

def about():
 current='about';h=inside(current,'About the collection','A life measured<br><em>in seasons.</em>','ANEVUM is an independent botanical and creative archive by Devon Alan Akins, documenting five seed-grown red maples from their earliest years.','∞')
 body=h+f'<section class="chapter on-paper"><div class="wrap two-column"><div>{eyebrow("The founding idea",False)}<h2 class="display sm">A collection<br>that <em>grows up.</em></h2><p class="text-prose">The five original Acer rubrum seedlings survive from the 2026 growing season. Their individual records will become richer over time through actual photography and careful observation, without rewriting their beginnings.</p>{A("Meet the collection","collection",current)}</div><div class="graphic-panel vignette">{image("hero-small.webp",current,"Illustrative young maple in a dark pot")}<div class="panel-folio"><strong>2026 and beyond.</strong><span>Illustrative environment, not collection photography</span></div></div></div></section><section class="chapter dark"><div class="wrap">{eyebrow("A place for family and time")}<h2 class="display sm">Living things are<br>never <em>finished.</em></h2><p class="text-prose">One of the red maples was chosen by a family member. A separately transplanted acorn is being observed as a provisional experiment. Their history is a part of this collection, but individual photographs and botanical identifications must be verified before publication as specimen evidence.</p>{A("Read the provisional field note","field-notes/acorn-01",current)}</div></section>'
 page(current,'About','An independent bonsai and penjing collection by Devon Alan Akins.',body)

def acorn():
 current='field-notes/acorn-01';h=inside(current,'Field experiment / provisional','The acorn<br><em>experiment.</em>','An acorn from compost, moved into a family growing pot, then transplanted into a small starter pot following disturbance. Its identity and survival remain to be confirmed.','?')
 meta=[('Collected from','Compost · approximate date not recorded'),('Observed on','15 November 2026'),('Identification','Acorn · probable oak / species unverified'),('Current status','Transplanted · establishment uncertain'),('Photo record','Authentic photography pending'),('Part of five maples','No')]
 dl='<dl class="metadata">'+''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in meta)+'</dl>'
 body=h+f'<section class="chapter on-paper"><div class="wrap two-column"><div>{eyebrow("Small field observation",False)}<h2 class="display sm">Maybe the start<br>of <em>something.</em></h2><p class="text-prose">The seed may have begun rooting, but repotting and disturbance make the outcome uncertain. It is tracked as a separate experiment, not presented as a sixth established bonsai.</p>{A("Return to the collection","collection",current)}</div><div>{dl}</div></div></section>'
 page(current,'The Acorn Experiment — Provisional','A provisional seed experiment, separate from the five founding red maples.',body)

if __name__=='__main__':
 homepage();collection()
 for s in SPECIMENS:specimen_page(s)
 chronicle();atelier();journal();journal_entry();practice();about();acorn()
 (R/'CONTENT-PROVENANCE.json').write_text(json.dumps({'specimens':SPECIMENS,'provisional':[{'name':'the acorn','species':'unknown (oak suspected)','status':'transplanted / establishment unverified','date':'2026-11-15'}], 'source':'User firsthand description, November 15–16 2026','media_kind':'illustrative','documentary_images':0},indent=2,ensure_ascii=False))
 print('Built',len(list(R.rglob('index.html'))),'page routes')
